+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+import QtQuick
+import QtQuick.Controls
+import QtQuick.Layouts
+import org.kde.kirigami as Kirigami
+import org.kde.kcmutils as KCM
+import org.kde.plasma.private.mpris as Mpris
+
+KCM.SimpleKCM {
+    id: page
+
+    property string cfg_preferredPlayer
+    property string cfg_preferredPlayerName
+
+    // Players that are running now, plus the saved one if it isn't
+    readonly property var players: {
+        const list = [{ id: "", name: i18nc("@item:inlistbox no preferred player", "None") }];
+        for (let i = 0; i < runningPlayers.count; ++i) {
+            const player = runningPlayers.objectAt(i);
+            if (!player || player.isMultiplexer) {
+                continue;
+            }
+            const id = player.desktopEntry || player.identity;
+            if (!list.some(p => p.id === id)) {
+                list.push({ id: id, name: player.identity });
+            }
+        }
+        if (page.cfg_preferredPlayer && !list.some(p => p.id === page.cfg_preferredPlayer)) {
+            list.push({ id: page.cfg_preferredPlayer, name: page.cfg_preferredPlayerName || page.cfg_preferredPlayer });
+        }
+        return list;
+    }
+
+    Mpris.Mpris2Model {
+        id: mpris2Model
+    }
+
+    Instantiator {
+        id: runningPlayers
+        model: mpris2Model
+        delegate: QtObject {
+            required property string desktopEntry
+            required property string identity
+            required property bool isMultiplexer
+        }
+    }
+
+    Kirigami.FormLayout {
+        ComboBox {
+            Kirigami.FormData.label: i18nc("@label:listbox", "Preferred player:")
+            model: page.players
+            textRole: "name"
+            valueRole: "id"
+            currentIndex: page.players.findIndex(p => p.id === page.cfg_preferredPlayer)
+            onActivated: index => {
+                page.cfg_preferredPlayer = page.players[index].id;
+                page.cfg_preferredPlayerName = page.players[index].id ? page.players[index].name : "";
+            }
+        }
+        Label {
+            Layout.fillWidth: true
+            text: i18nc("@info", "When this player is running, the widget always controls it.")
+            textFormat: Text.PlainText
+            wrapMode: Text.Wrap
+            font: Kirigami.Theme.smallFont
+        }
+    }
+}
