diff --git a/libkmpris/mpris2model.cpp b/libkmpris/mpris2model.cpp
index 98ee626bc6..4e864dc9b0 100644
--- a/libkmpris/mpris2model.cpp
+++ b/libkmpris/mpris2model.cpp
@@ -66,6 +66,47 @@ PlayerContainer *Mpris2Model::currentPlayer() const
     return m_currentPlayer;
 }

+QString Mpris2Model::preferredPlayer() const
+{
+    return m_preferredPlayer;
+}
+
+void Mpris2Model::setPreferredPlayer(const QString &preferredPlayer)
+{
+    if (m_preferredPlayer == preferredPlayer) {
+        return;
+    }
+
+    m_preferredPlayer = preferredPlayer;
+    Q_EMIT preferredPlayerChanged();
+    selectPreferredPlayer();
+}
+
+bool Mpris2Model::isPreferredPlayer(const QModelIndex &idx) const
+{
+    if (m_preferredPlayer.isEmpty() || idx.data(Mpris2SourceModel::IsMultiplexerRole).toBool()) {
+        return false;
+    }
+    return idx.data(Mpris2SourceModel::DesktopEntryRole).toString() == m_preferredPlayer
+        || idx.data(Mpris2SourceModel::IdentityRole).toString() == m_preferredPlayer;
+}
+
+void Mpris2Model::selectPreferredPlayer()
+{
+    for (int i = 0, size = rowCount(); i < size; ++i) {
+        const QModelIndex idx = index(i, 0);
+        if (isPreferredPlayer(idx)) {
+            if (m_currentIndex != static_cast<unsigned>(i)) {
+                m_currentIndex = i;
+                m_currentPlayer = idx.data(Mpris2SourceModel::ContainerRole).value<PlayerContainer *>();
+                Q_EMIT currentPlayerChanged();
+                Q_EMIT currentIndexChanged();
+            }
+            return;
+        }
+    }
+}
+
 PlayerContainer *Mpris2Model::playerForLauncherUrl(const QUrl &launcherUrl, unsigned pid) const
 {
     if (launcherUrl.isEmpty()) {
@@ -114,7 +155,7 @@ PlayerContainer *Mpris2Model::playerForLauncherUrl(const QUrl &launcherUrl, unsi
     }
 }

-void Mpris2Model::onRowsInserted(const QModelIndex &, int first, int)
+void Mpris2Model::onRowsInserted(const QModelIndex &, int first, int last)
 {
     if (!m_currentPlayer) {
         m_currentIndex = first;
@@ -122,6 +163,14 @@ void Mpris2Model::onRowsInserted(const QModelIndex &, int first, int)
         Q_EMIT currentPlayerChanged();
         Q_EMIT currentIndexChanged();
     }
+    // Also check when the multiplexer is inserted, as it shifts the other rows
+    for (int i = first; i <= last; ++i) {
+        const QModelIndex idx = index(i, 0);
+        if (isPreferredPlayer(idx) || idx.data(Mpris2SourceModel::IsMultiplexerRole).toBool()) {
+            selectPreferredPlayer();
+            break;
+        }
+    }
 }

 void Mpris2Model::onRowsAboutToBeRemoved(const QModelIndex &, int first, int)
